/// The rare word of `ch`, from packtab's [2^8,2^6,2^2] layout: three reads.
#[allow(
    clippy::unnecessary_cast,
    reason = "packtab casts every index to usize, whatever its type"
)]
#[inline]
pub(super) fn rare_word(ch: char) -> u32 {
    let u = ch as usize;
    if u < 1114112usize {
        (at(
            &RARE_U32,
            ((at(
                &RARE_U16,
                (((at(&RARE_U8, ((((u) >> 2) >> 6) as usize) as usize)) as usize) << 6) as usize
                    + (((u) >> 2) & 63) as usize,
            )) as usize) as usize
                + ((u) & 3) as usize,
        )) as u32
    } else {
        0
    }
}

/// `table[i]`, or zero past the end of `table`.
///
/// No index a lookup computes is past the end: the sweep test visits every
/// character. The zero is there so that no input can reach a panic.
#[inline(always)]
fn at<T: Copy + Default>(table: &[T], i: usize) -> T {
    match table.get(i) {
        Some(value) => *value,
        None => T::default(),
    }
}
